import{_ as n,c as i,o as t,a2 as a}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"Kontakt","description":"Holen Sie sich Hilfe zu qDiff per E-Mail und erfahren Sie, welche Angaben uns eine schnelle Hilfe ermöglichen.","frontmatter":{"title":"Kontakt","description":"Holen Sie sich Hilfe zu qDiff per E-Mail und erfahren Sie, welche Angaben uns eine schnelle Hilfe ermöglichen."},"headers":[],"relativePath":"de/guide/support.md","filePath":"de/guide/support.md","lastUpdated":1794296122000}'),r={name:"de/guide/support.md"};function s(h,e,l,u,o,c){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h1><p>Etwas Unklares, eine Datei, die sich nicht öffnen lässt, eine Idee für die nächste Version — wir lesen jede Nachricht.</p><p><strong>E-Mail:</strong> <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a></p><p>Sie können auf Deutsch oder Englisch schreiben.</p><h2 id="was-uns-hilft-ihnen-zu-helfen" tabindex="-1">Was uns hilft, Ihnen zu helfen <a class="header-anchor" href="#was-uns-hilft-ihnen-zu-helfen" aria-label="Permalink to &quot;Was uns hilft, Ihnen zu helfen&quot;">​</a></h2><ul><li>Ihre macOS-Version und welchen Mac Sie nutzen.</li><li>Die qDiff-Version (öffnen Sie <strong>Über qDiff</strong> im App-Menü).</li><li>Was Sie verglichen haben und was Sie erwartet haben zu sehen.</li><li>Ein Screenshot, falls das Problem auf dem Bildschirm sichtbar ist.</li></ul><p>Bitte hängen Sie keine Dateien an, die Sie lieber nicht teilen möchten — eine Beschreibung oder ein zugeschnittener Screenshot genügt meist.</p><h2 id="bevor-sie-schreiben" tabindex="-1">Bevor Sie schreiben <a class="header-anchor" href="#bevor-sie-schreiben" aria-label="Permalink to &quot;Bevor Sie schreiben&quot;">​</a></h2><p>Die <a href="./faq.html">FAQ</a> beantwortet die häufigsten Fragen, und die <a href="./introduction.html">Einführung</a> führt Sie durch den ersten Vergleich. Falls sich Ihre Frage auf den Datenschutz bezieht, erläutert die <a href="./../privacy/">Datenschutzerklärung</a> genau, was qDiff liest und was nicht.</p><h2 id="zu-kaufen-und-erstattungen" tabindex="-1">Zu Käufen und Erstattungen <a class="header-anchor" href="#zu-kaufen-und-erstattungen" aria-label="Permalink to &quot;Zu Käufen und Erstattungen&quot;">​</a></h2><p>Käufe und Erstattungen werden über den Mac App Store und Ihre Apple ID abgewickelt. Bei Fragen zur Abrechnung ist der Apple Support der schnellste Weg; zur Wiederherstellung eines Kaufs innerhalb von qDiff sehen Sie in die <a href="./faq.html">FAQ</a>.</p>',11)])])}const p=n(r,[["render",s]]);export{f as __pageData,p as default};
